"""miner_3 2026-07-30: pairwise correlation analysis for passing candidates vs
existing library factor signals (recomputed from expressions) to ensure the
persisted set is mutually distinct (pairwise |rho| < 0.5 preferred)."""
import sys
sys.path.insert(0, "scripts")
import numpy as np
import pandas as pd
from miner3_lib import build_panel, VISIBLE

prices = build_panel()
panel = pd.DataFrame(prices)
ret = panel.pct_change()


def per_asset(func):
    out = {}
    for a in panel.columns:
        s = panel[a].dropna()
        out[a] = func(s).reindex(panel.index)
    return pd.DataFrame(out, index=panel.index)


def f_zscore(s, w=60):
    return (s - s.rolling(w).mean()) / s.rolling(w).std()


def f_mom(s, w=252, skip=21):
    return s.shift(skip) / s.shift(skip + w) - 1.0


def f_upday(s, w=20):
    return (s.pct_change() > 0).rolling(w).mean()


def f_vol_mom(s, w1=20, w2=60):
    r = s.pct_change()
    mom = s / s.shift(w1) - 1.0
    return np.sign(mom) * r.rolling(w2).std()


def f_mom10(s):
    return s.shift(5) / s.shift(15) - 1.0


def f_mom120(s):
    return s.shift(5) / s.shift(125) - 1.0


def f_vov(s):
    r = s.pct_change()
    return r.rolling(20).std().rolling(60).std()


signals = {
    "cand_price_zscore_60": per_asset(lambda s: f_zscore(s, 60)),
    "cand_mom_252_skip21": per_asset(lambda s: f_mom(s, 252, 21)),
    "cand_upday_ratio_20": per_asset(lambda s: f_upday(s, 20)),
    "cand_vol_mom_signed_20x60": per_asset(lambda s: f_vol_mom(s, 20, 60)),
    "lib_mom_10d_skip5": per_asset(f_mom10),
    "lib_mom_120d_skip5": per_asset(f_mom120),
    "lib_vol_of_vol20x60": per_asset(f_vov),
}
# vix_beta_cond_60x20 uses VIX macro; approximate with BTC as risk proxy is not valid -
# instead recompute true VIX beta conditional factor
vix = pd.read_csv("../persistent/index_data/VIX.csv", parse_dates=["date"])
vix = vix[vix["date"] <= pd.Timestamp(VISIBLE)].set_index("date")["close"].astype(float)
vr = vix.pct_change()
vix_ret = vr.reindex(panel.index)


def rolling_beta(r, m, win=60):
    z = pd.concat([r.rename("a"), m.rename("m")], axis=1).dropna()
    cov = z["a"].rolling(win).cov(z["m"])
    var = z["m"].rolling(win).var()
    return (cov / var).reindex(r.index)


def f_vix_beta(s):
    r = s.pct_change()
    beta = rolling_beta(r, vix_ret, 60)
    cond = vix_ret.rolling(20).mean() * -1.0  # conditional on VIX falling over 20d (risk-on)
    return beta * cond
signals["lib_vix_beta_cond_60x20"] = per_asset(f_vix_beta)

names = list(signals.keys())
print("pairwise pooled Pearson |rho| on raw factor values (union reindex):")
print(f"{'':28s}" + "".join(f"{n[5:22]:>18s}" for n in names))
rho = pd.DataFrame(index=names, columns=names, dtype=float)
for i, a in enumerate(names):
    row = []
    for j, b in enumerate(names):
        x = signals[a].stack()
        y = signals[b].stack()
        both = pd.concat([x.rename("x"), y.rename("y")], axis=1).dropna()
        c = float(both["x"].corr(both["y"])) if len(both) > 100 else np.nan
        rho.loc[a, b] = c
        row.append(c)
    print(f"{a:28s}" + "".join(f"{c:>18.3f}" for c in row))

print("\nmax |rho| of each candidate vs library factors (lib_*):")
for a in ["cand_price_zscore_60", "cand_mom_252_skip21", "cand_upday_ratio_20", "cand_vol_mom_signed_20x60"]:
    libs = [rho.loc[a, b] for b in names if b.startswith("lib_")]
    print(f"  {a:28s} max_abs={max(abs(c) for c in libs):.3f}  all={[round(c,3) for c in libs]}")

print("\nmax |rho| among candidates (pairwise):")
cands = [a for a in names if a.startswith("cand_")]
for i, a in enumerate(cands):
    for b in cands[i + 1:]:
        print(f"  {a[5:]:24s} vs {b[5:]:24s} rho={rho.loc[a, b]:+.3f}")

"""miner_3 2026-07-30: correlation check round 2 - include mkt_beta_20 & max_ret_20."""
import sys
sys.path.insert(0, "scripts")
import numpy as np
import pandas as pd
from miner3_lib import build_panel, VISIBLE

prices = build_panel()
panel = pd.DataFrame(prices)
ret = panel.pct_change()


def per_asset(func):
    out = {}
    for a in panel.columns:
        s = panel[a].dropna()
        out[a] = func(s).reindex(panel.index)
    return pd.DataFrame(out, index=panel.index)


def f_zscore(s, w=60):
    return (s - s.rolling(w).mean()) / s.rolling(w).std()


def f_upday(s, w=20):
    return (s.pct_change() > 0).rolling(w).mean()


def f_maxret(s, w=20):
    return s.pct_change().rolling(w).max()


def f_mom10(s):
    return s.shift(5) / s.shift(15) - 1.0


def f_mom120(s):
    return s.shift(5) / s.shift(125) - 1.0


def f_vov(s):
    return s.pct_change().rolling(20).std().rolling(60).std()


market = ret.mean(axis=1)
def f_mktbeta(s, w=20):
    r = s.pct_change()
    z = pd.concat([r.rename("a"), market.rename("m")], axis=1).dropna()
    cov = z["a"].rolling(w).cov(z["m"])
    var = z["m"].rolling(w).var()
    return (cov / var).reindex(r.index)


signals = {
    "cand_price_zscore_60": per_asset(lambda s: f_zscore(s, 60)),
    "cand_upday_ratio_20": per_asset(lambda s: f_upday(s, 20)),
    "cand_max_ret_20": per_asset(lambda s: f_maxret(s, 20)),
    "cand_mkt_beta_20": per_asset(lambda s: f_mktbeta(s, 20)),
    "lib_mom_10d_skip5": per_asset(f_mom10),
    "lib_mom_120d_skip5": per_asset(f_mom120),
    "lib_vol_of_vol20x60": per_asset(f_vov),
}
names = list(signals.keys())
rho = pd.DataFrame(index=names, columns=names, dtype=float)
print(f"{'':28s}" + "".join(f"{n[5:20]:>16s}" for n in names))
for i, a in enumerate(names):
    row = []
    for j, b in enumerate(names):
        both = pd.concat([signals[a].stack().rename("x"), signals[b].stack().rename("y")], axis=1).dropna()
        c = float(both["x"].corr(both["y"])) if len(both) > 100 else np.nan
        rho.loc[a, b] = c
        row.append(c)
    print(f"{a:28s}" + "".join(f"{c:>16.3f}" for c in row))

print("\nmax |rho| of each candidate vs library factors (lib_*):")
for a in ["cand_price_zscore_60", "cand_upday_ratio_20", "cand_max_ret_20", "cand_mkt_beta_20"]:
    libs = [rho.loc[a, b] for b in names if b.startswith("lib_")]
    print(f"  {a:24s} max_abs={max(abs(c) for c in libs):.3f}  all={[round(c,3) for c in libs]}")

print("\nmax |rho| among candidates:")
cands = [a for a in names if a.startswith("cand_")]
for i, a in enumerate(cands):
    for b in cands[i + 1:]:
        print(f"  {a[5:]:22s} vs {b[5:]:22s} rho={rho.loc[a, b]:+.3f}")

"""miner_3 2026-07-30: validate 4 new candidates + re-validate 4 library factors."""
import sys
sys.path.insert(0, "scripts")
import numpy as np
import pandas as pd
from miner3_lib import build_panel, forward_returns, spearman_ic, mean_rank_turnover, ADMISSION_HORIZON

prices = build_panel()
panel = pd.DataFrame(prices)
ret = panel.pct_change()


def per_asset(func):
    out = {}
    for a in panel.columns:
        s = panel[a].dropna()
        out[a] = func(s).reindex(panel.index)
    return pd.DataFrame(out, index=panel.index)


def f_zscore(s, w=60):
    return (s - s.rolling(w).mean()) / s.rolling(w).std()


def f_upday(s, w=20):
    return (s.pct_change() > 0).rolling(w).mean()


def f_maxret(s, w=20):
    return s.pct_change().rolling(w).max()


market = ret.mean(axis=1)
def f_mktbeta(s, w=20):
    r = s.pct_change()
    z = pd.concat([r.rename("a"), market.rename("m")], axis=1).dropna()
    cov = z["a"].rolling(w).cov(z["m"])
    var = z["m"].rolling(w).var()
    return (cov / var).reindex(r.index)


def f_mom10(s):
    return s.shift(5) / s.shift(15) - 1.0


def f_mom120(s):
    return s.shift(5) / s.shift(125) - 1.0


def f_vov(s):
    return s.pct_change().rolling(20).std().rolling(60).std()


cands = {
    "cand_price_zscore_60": per_asset(lambda s: f_zscore(s, 60)),
    "cand_upday_ratio_20": per_asset(lambda s: f_upday(s, 20)),
    "cand_max_ret_20": per_asset(lambda s: f_maxret(s, 20)),
    "cand_mkt_beta_20": per_asset(lambda s: f_mktbeta(s, 20)),
    "lib_mom_10d_skip5": per_asset(f_mom10),
    "lib_mom_120d_skip5": per_asset(f_mom120),
    "lib_vol_of_vol20x60": per_asset(f_vov),
}

fwd = forward_returns(prices, ADMISSION_HORIZON)
for name, fdf in cands.items():
    ic_series = spearman_ic(fdf, fwd)
    ic = float(ic_series.mean())
    icir = float(ic_series.mean() / ic_series.std()) if ic_series.std() > 0 else 0.0
    turn = mean_rank_turnover(fdf)
    print(f"{name:24s} n={len(ic_series):5d} ic={ic:+.4f} icir={icir:+.4f} "
          f"|ic|={abs(ic):.4f} |icir|={abs(icir):.4f} pass_gate={'YES' if abs(ic)>=0.007 and abs(icir)>=0.084 else 'no'} "
          f"turn={turn:.3f}")

"""miner_3 2026-07-30: full pairwise rho incl. vix_beta + self-contained expression test."""
import sys, json
sys.path.insert(0, "scripts")
import numpy as np
import pandas as pd
from miner3_lib import build_panel, load_obs

prices = build_panel()
panel = pd.DataFrame(prices)
ret = panel.pct_change()
vix = load_obs('VIX')


def per_asset(func, extra=None):
    out = {}
    for a in panel.columns:
        s = panel[a].dropna()
        out[a] = func(s, extra).reindex(panel.index) if extra is not None else func(s).reindex(panel.index)
    return pd.DataFrame(out, index=panel.index)


def f_zscore(s, w=60):
    return (s - s.rolling(w).mean()) / s.rolling(w).std()


def f_upday(s, w=20):
    return (s.pct_change() > 0).rolling(w).mean()


def f_maxret(s, w=20):
    return s.pct_change().rolling(w).max()


market = ret.mean(axis=1)
def f_mktbeta(s, w=20):
    r = s.pct_change()
    z = pd.concat([r.rename("a"), market.rename("m")], axis=1).dropna()
    cov = z["a"].rolling(w).cov(z["m"])
    var = z["m"].rolling(w).var()
    return (cov / var).reindex(r.index)


def f_mom10(s):
    return s.shift(5) / s.shift(15) - 1.0


def f_mom120(s):
    return s.shift(5) / s.shift(125) - 1.0


def f_vov(s):
    return s.pct_change().rolling(20).std().rolling(60).std()


def f_vixbeta_cond(s, v):
    """-beta(asset_ret, vix_ret, 60) * vix_20d_mom"""
    r = s.pct_change().rename('a')
    vr = v.pct_change().rename('v')
    z = pd.concat([r, vr], axis=1).dropna()
    beta = (z['a'].rolling(60).cov(z['v']) / z['v'].rolling(60).var())
    vix_mom = v / v.shift(20) - 1.0
    return (-beta * vix_mom.reindex(z.index)).reindex(s.index)


signals = {
    "cand_price_zscore_60": per_asset(lambda s: f_zscore(s, 60)),
    "cand_upday_ratio_20": per_asset(lambda s: f_upday(s, 20)),
    "cand_mkt_beta_20": per_asset(lambda s: f_mktbeta(s, 20)),
    "lib_mom_10d_skip5": per_asset(f_mom10),
    "lib_mom_120d_skip5": per_asset(f_mom120),
    "lib_vol_of_vol20x60": per_asset(f_vov),
    "lib_vix_beta_cond_60x20": per_asset(f_vixbeta_cond, extra=vix),
}
names = list(signals.keys())
rho = pd.DataFrame(index=names, columns=names, dtype=float)
for i, a in enumerate(names):
    for j, b in enumerate(names):
        both = pd.concat([signals[a].stack().rename("x"), signals[b].stack().rename("y")], axis=1).dropna()
        c = float(both["x"].corr(both["y"])) if len(both) > 100 else np.nan
        rho.loc[a, b] = c

print("pairwise |rho| matrix (lower triangle):")
for i, a in enumerate(names):
    row = "".join(f"{rho.loc[a,b]:>8.3f}" if j <= i else "        " for j, b in enumerate(names))
    print(f"{a[5:]:22s}{row}")

print("\nmax |rho| vs library (lib_*):")
for a in [n for n in names if n.startswith('cand_')]:
    libs = [rho.loc[a, b] for b in names if b.startswith('lib_')]
    print(f"  {a:24s} max_abs={max(abs(c) for c in libs):.3f} all={[round(c,3) for c in libs]}")

print("\nmax |rho| among library factors:")
for i, a in enumerate([n for n in names if n.startswith('lib_')]):
    for b in [n for n in names if n.startswith('lib_')]:
        if a < b:
            print(f"  {a[4:]:22s} vs {b[4:]:22s} rho={rho.loc[a,b]:+.3f}")

# --- self-contained expression test under the gate namespace ---
print("\n--- self-contained expression eval test (gate namespace: close, pct_change, pd, np) ---")
env = {'pd': pd, 'np': np, 'close': panel, 'pct_change': ret}
exprs = {
    'lib_mom_10d_skip5': 'close.shift(5) / close.shift(15) - 1.0',
